  InvalidParams: -32602,
  InternalError: -32603,
  Unauthorized: -32000,
  Forbidden: -32001,
  NotFound: -32002,
  LeaseExpired: -32003,
  Timeout: -32004,
  Canceled: -32005,
  PayloadTooLarge: -32006,
  SessionNotActive: -32007,
  McpUnavailable: -32008,
